import React, { ReactNode, useState, useEffect } from 'react';
import { motion, useAnimationControls } from 'framer-motion';
import AnimatedText from './AnimatedText';

interface AnimatedListProps {
  items: ReactNode[];
  className?: string;
  itemClassName?: string;
  staggerDelay?: number;
  staggerVariation?: number;
  onAnimationComplete?: () => void;
}

/**
 * AnimatedList - A component that guarantees strictly sequential animations
 * Each item waits for the previous one to complete before starting
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  items,
  className = '',
  itemClassName = '',
  staggerDelay = 0.03,
  staggerVariation = 0,
  onAnimationComplete
}) => {
  // Track which item is currently animating
  const [currentItemIndex, setCurrentItemIndex] = useState<number>(0);
  const controls = useAnimationControls();

  // This effect manages the sequential animation of items
  useEffect(() => {
    // Start animation for current item
    if (currentItemIndex < items.length) {
      controls.start(`visible-${currentItemIndex}`);
    } else if (currentItemIndex === items.length && onAnimationComplete) {
      // All items have been animated
      onAnimationComplete();
    }
  }, [currentItemIndex, items.length, controls, onAnimationComplete]);

  // Handle completion of an item's animation
  const handleItemComplete = (index: number) => {
    // Move to the next item after a short pause
    setTimeout(() => {
      setCurrentItemIndex(index + 1);
    }, 100); // Small pause between items
  };

  // Create variants for each item to control sequencing
  const itemVariants = {};

  // Generate a variant for each item
  items.forEach((_, index) => {
    itemVariants[`visible-${index}`] = {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.25,
        ease: "easeOut"
      }
    };
  });

  // Add hidden state
  itemVariants.hidden = {
    opacity: 0,
    y: 5,
    transition: {
      duration: 0.1
    }
  };

  // Convert each item to handle both string and ReactNode
  const processItem = (content: ReactNode, index: number) => {
    // For string content, wrap in AnimatedText
    if (typeof content === 'string') {
      return <AnimatedText key={index} text={content} />;
    }

    // If it's already a React element, return it
    return content;
  };

  return (
    <motion.ul
      className={className}
      initial="hidden"
      animate={controls}
      style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'flex-start',
        padding: 0,
        margin: 0,
        listStyle: 'none'
      }}
    >
      {items.map((itemContent, index) => (
        <motion.li 
          key={index}
          className={itemClassName}
          custom={index}
          variants={itemVariants}
          initial="hidden"
          animate={currentItemIndex >= index ? `visible-${index}` : "hidden"}
          onAnimationComplete={() => {
            if (currentItemIndex === index) {
              handleItemComplete(index);
            }
          }}
          style={{ width: '100%', justifyContent: 'flex-start' }}
        >
          {processItem(itemContent, index)}
        </motion.li>
      ))}
    </motion.ul>
  );
};

export default AnimatedList;
